 4	# Submit a return
 5	
 6	- A customer returns some items of a delivered order, within 30 days of delivery {#partial-return}
 7	  e.g. two jackets and a map delivered on 1 January -> on 20 January the customer returns one jacket
 8	- A return never covers more of an item than the order holds {#not-more-than-ordered}
 9	  e.g. one pair of socks ordered -> returning two is refused
10	- The refund is the price paid for the returned items, with the order's discount applied and rounded half up to the cent {#partial-refund}
11	  e.g. a trail map at 8.50 on an order with 33% off -> a refund of 5.70
12	- A return is requested, then approved by support, then refunded, in that order {#status-flow}
13	  e.g. refunding a return support hasn't approved -> refused

 1	import type { Order } from "./orders";
 2	
 3	export type ReturnItem = { productId: string; quantity: number };
 4	export type ReturnStatus = "requested" | "approved" | "refunded";
 5	export type Return = {
 6	  id: string;
 7	  orderId: string;
 8	  items: ReturnItem[];
 9	  refundCents: number;
10	  status: ReturnStatus;
11	  requestedAt: Date;
12	};
13	
14	export const RETURN_WINDOW_DAYS = 30;
15	const DAY_MS = 86_400_000;
16	let nextId = 1;
17	
18	export function calculateRefund(order: Order, items: ReturnItem[]): number {
19	  const subtotal = items.reduce((sum, item) => {
20	    const line = order.lines.find((l) => l.productId === item.productId);
21	    if (!line) throw new Error(`Product ${item.productId} is not on order ${order.id}`);
22	    return sum + line.unitPriceCents * item.quantity;
23	  }, 0);
24	  return Math.round(subtotal * (1 - order.discountPercent / 100));
25	}
26	
27	export function submitReturn(order: Order, items: ReturnItem[], now: Date = new Date()): Return {
28	  if (order.status !== "delivered" || !order.deliveredAt) {
29	    throw new Error("Only delivered orders can be returned");
30	  }
31	  const ageDays = (now.getTime() - order.deliveredAt.getTime()) / DAY_MS;
32	  if (ageDays > RETURN_WINDOW_DAYS) {
33	    throw new Error(`Returns are accepted within ${RETURN_WINDOW_DAYS} days of delivery`);
34	  }
35	  if (items.length === 0) throw new Error("A return needs at least one item");
36	  for (const item of items) {
37	    const line = order.lines.find((l) => l.productId === item.productId);
38	    if (!line) throw new Error(`Product ${item.productId} is not on order ${order.id}`);
39	    if (!Number.isInteger(item.quantity) || item.quantity < 1) {
40	      throw new Error("Quantity must be a whole number of at least 1");
41	    }
42	    if (item.quantity > line.quantity) {
43	      throw new Error(`Cannot return more ${item.productId} than were ordered`);
44	    }
45	  }
46	  return {
47	    id: `return-${nextId++}`,
48	    orderId: order.id,
49	    items: items.map((i) => ({ ...i })),
50	    refundCents: calculateRefund(order, items),
51	    status: "requested",
52	    requestedAt: now,
53	  };
54	}
55	
56	export function approveReturn(ret: Return): Return {
57	  if (ret.status !== "requested") throw new Error(`A ${ret.status} return cannot be approved`);
58	  return { ...ret, status: "approved" };
59	}
60	
61	export function refundReturn(ret: Return): Return {
62	  if (ret.status !== "approved") throw new Error("Only an approved return can be refunded");
63	  return { ...ret, status: "refunded" };
64	}

 1	import { describe, expect, test } from "bun:test";
 2	import { createOrder, markDelivered } from "../src/orders";
 3	import { approveReturn, refundReturn, submitReturn } from "../src/returns";
 4	
 5	const deliveredAt = new Date("2026-01-01");
 6	const inWindow = new Date("2026-01-20");
 7	
 8	function deliveredOrder(lines: { productId: string; quantity: number }[], discountPercent = 0) {
 9	  return markDelivered(createOrder({ customerId: "sanne", lines, discountPercent }), deliveredAt);
10	}
11	
12	describe("returns", () => {
13	  test("refunds only the returned items of an order", () => {
14	    const order = deliveredOrder([
15	      { productId: "rain-jacket", quantity: 2 },
16	      { productId: "trail-map", quantity: 1 },
17	    ]);
18	    const ret = submitReturn(order, [{ productId: "rain-jacket", quantity: 1 }], inWindow);
19	    expect(ret.refundCents).toBe(1990);
20	    expect(ret.status).toBe("requested");
21	  });
22	
23	  test("applies the order discount to the refund", () => {
24	    const order = deliveredOrder([{ productId: "water-bottle", quantity: 1 }], 10);
25	    const ret = submitReturn(order, [{ productId: "water-bottle", quantity: 1 }], inWindow);
26	    expect(ret.refundCents).toBe(1800);
27	  });
28	
29	  test("rejects more items than were ordered", () => {
30	    const order = deliveredOrder([{ productId: "wool-socks", quantity: 1 }]);
31	    expect(() => submitReturn(order, [{ productId: "wool-socks", quantity: 2 }], inWindow)).toThrow(
32	      "more wool-socks than were ordered",
33	    );
34	  });
35	
36	  test("rejects a product that is not on the order", () => {
37	    const order = deliveredOrder([{ productId: "wool-socks", quantity: 1 }]);
38	    expect(() => submitReturn(order, [{ productId: "headlamp", quantity: 1 }], inWindow)).toThrow("not on order");
39	  });
40	
41	  test("rejects an order that has not been delivered", () => {
42	    const order = createOrder({ customerId: "sanne", lines: [{ productId: "wool-socks", quantity: 1 }] });
43	    expect(() => submitReturn(order, [{ productId: "wool-socks", quantity: 1 }], inWindow)).toThrow(
44	      "Only delivered orders",
45	    );
46	  });
47	
48	  test("accepts a return on day 30 and rejects it after", () => {
49	    const order = deliveredOrder([{ productId: "wool-socks", quantity: 1 }]);
50	    expect(submitReturn(order, [{ productId: "wool-socks", quantity: 1 }], new Date("2026-01-31")).status).toBe(
51	      "requested",
52	    );
53	    expect(() => submitReturn(order, [{ productId: "wool-socks", quantity: 1 }], new Date("2026-02-05"))).toThrow(
54	      "within 30 days",
55	    );
56	  });
57	
58	  test("moves from requested to approved to refunded, in that order", () => {
59	    const order = deliveredOrder([{ productId: "wool-socks", quantity: 1 }]);
60	    const requested = submitReturn(order, [{ productId: "wool-socks", quantity: 1 }], inWindow);
61	    expect(() => refundReturn(requested)).toThrow("Only an approved return");
62	    const approved = approveReturn(requested);
63	    expect(approved.status).toBe("approved");
64	    expect(() => approveReturn(approved)).toThrow("cannot be approved");
65	    expect(refundReturn(approved).status).toBe("refunded");
66	  });
67	});

